import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';

const LoginPage = () => {
  // State for the form inputs
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  // State for loading and error messages
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const navigate = useNavigate();

  // Handle form submission
  const submitHandler = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      // The data to be sent to the backend
      const config = {
        headers: {
          'Content-Type': 'application/json',
        },
      };
      const { data } = await axios.post(
        '/api/users/login',
        { email, password },
        config
      );

      // On successful login, save user info to localStorage
      localStorage.setItem('userInfo', JSON.stringify(data));
      
      setLoading(false);
      
      // Redirect to the homepage
      navigate('/');

    } catch (err) {
      setLoading(false);
      // Set error message from backend response
      setError(err.response && err.response.data.message ? err.response.data.message : err.message);
    }
  };

  return (
    <div className="container mx-auto flex justify-center items-center h-[80vh]">
      <div className="w-full max-w-md">
        <form 
          onSubmit={submitHandler} 
          className="bg-white shadow-2xl rounded-xl px-8 pt-6 pb-8 mb-4"
        >
          <h1 className="text-3xl font-bold mb-6 text-center text-stone-gray">Sign In</h1>
          
          {error && <div className="bg-red-100 text-red-700 p-3 rounded mb-4">{error}</div>}
          {loading && <div className="text-center mb-4">Loading...</div>}

          <div className="mb-4">
            <label className="block text-stone-gray text-sm font-bold mb-2" htmlFor="email">
              Email Address
            </label>
            <input
              className="shadow appearance-none border rounded w-full py-2 px-3 text-stone-gray leading-tight focus:outline-none focus:shadow-outline"
              id="email"
              type="email"
              placeholder="Enter email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div className="mb-6">
            <label className="block text-stone-gray text-sm font-bold mb-2" htmlFor="password">
              Password
            </label>
            <input
              className="shadow appearance-none border rounded w-full py-2 px-3 text-stone-gray mb-3 leading-tight focus:outline-none focus:shadow-outline"
              id="password"
              type="password"
              placeholder="Enter password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          <div className="flex items-center justify-between">
            <button
              className="bg-leaf-green hover:bg-forest-green text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline w-full disabled:bg-gray-400"
              type="submit"
              disabled={loading}
            >
              {loading ? 'Signing In...' : 'Sign In'}
            </button>
          </div>
          <div className="text-center mt-4">
            <p className="text-stone-gray text-sm">
              New Customer?{' '}
              <Link to="/register" className="font-bold text-leaf-green hover:text-forest-green">
                Register
              </Link>
            </p>
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginPage;
